{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Notification sent via independent mechanism upon adding authenticator",
      "covers": [
        "KDH-012"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with at least one active authenticator. The representative has a valid, independent notification channel (e.g., email or SMS) configured and verified.",
      "test_inputs": "A new authenticator (e.g., a new mobile device or hardware token) to be bound to the account.",
      "assumptions": "The 'independent mechanism' is defined as a channel distinct from the session used to bind the authenticator (e.g., email/SMS if binding is done via web session).",
      "steps": [
        {
          "no": 1,
          "action": "Log in to the VBP portal as the company representative using an existing authenticator.",
          "expected": "The representative is successfully authenticated and can access account management settings."
        },
        {
          "no": 2,
          "action": "Initiate the process to add a new authenticator to the account and complete the binding process successfully.",
          "expected": "The new authenticator is successfully bound to the account. The binding transaction completes without error."
        },
        {
          "no": 3,
          "action": "Check the independent notification channel (e.g., email inbox or SMS) associated with the representative's account.",
          "expected": "A notification message is received indicating that a new authenticator has been added to the account. The notification is delivered via a channel different from the one used to perform the binding action."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Notification mechanism independence verification",
      "covers": [
        "KDH-012"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account exists. The representative is currently logged in via a web browser session.",
      "test_inputs": "A new authenticator to be bound.",
      "assumptions": "The system supports email notifications as an independent mechanism.",
      "steps": [
        {
          "no": 1,
          "action": "Bind a new authenticator to the account while logged in via the web browser.",
          "expected": "The binding is successful."
        },
        {
          "no": 2,
          "action": "Verify that the notification regarding the new authenticator is not displayed solely within the current web session interface but is sent to an external channel (e.g., email).",
          "expected": "The notification is sent to the external channel (email). It is not merely a transient message within the same web session that performed the binding, ensuring the mechanism is independent of the binding transaction's endpoint."
        }
      ]
    }
  ]
}

