        },
        {
          "no": 2,
          "action": "Complete the binding process by providing the required binding code and verifying via the independent notification mechanism.",
          "expected": "The new telephone number is successfully bound as the new authenticator for SMS codes. The old number is no longer valid for SMS authentication."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Direct update of phone number without binding process is rejected",
      "covers": [
        "KDH-009"
      ],
