          "action": "Simulate the loss of the safe radio connection via EURORADIO indication.",
          "expected": "The OBU immediately initiates a request to set up a new safe radio connection using the same radio system as the previous successful connection."
        },
        {
          "no": 2,
          "action": "Monitor the OBU's radio interface activity.",
          "expected": "No delay is observed between the EURORADIO loss indication and the start of the reconnection attempt."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Reconnection attempt stops when session is terminated by timeout",
      "covers": [
        "ETC-011"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "An established communication session exists. The safe radio connection is lost. The defined time for maintaining the session (per A.3.1) is known and can be monitored.",
      "test_inputs": "Simulated loss of safe radio connection. No successful reconnection occurs within the defined time.",
