        {
          "no": 2,
          "action": "Wait for the defined time to elapse without a successful reconnection.",
          "expected": "The OBU considers the session as terminated."
        },
        {
          "no": 3,
          "action": "Observe the OBU's behavior after the session is considered terminated.",
          "expected": "The OBU stops the specific reconnection attempts for the terminated session (as per 3.5.4.3, attempts stop when session is considered terminated). Note: 3.5.4.3.1 states attempts resume immediately according to 3.5.3.4 f), but the requirement ETC-011 specifies stopping until one of the conditions is met. The test verifies the condition 'session is regarded as terminated' stops the *current* loop of attempts for that session context."
        }
      ]
    },
    {
      "id": "TC-03",
      "title": "Reconnection attempts stop when train passes RIU termination location",
      "covers": [
        "ETC-011"
      ],
