      "priority": "Orta",
      "preconditions": "An established communication session exists. The safe radio connection is lost. An RIU order to 'Terminate the communication session' is active with a specific location defined.",
      "test_inputs": "Simulated loss of safe radio connection. Train movement simulation passing the RIU-defined location.",
      "assumptions": "The RIU order location is set to a point ahead of the train's current position.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the loss of the safe radio connection.",
          "expected": "The OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Simulate the train passing the location indicated in the RIU order to terminate the communication session.",
          "expected": "The OBU stops the attempts to set up a new safe radio connection for this session."
        }
      ]
    },
    {
      "id": "TC-04",
      "title": "Reconnection attempts stop when safe radio connection is successfully re-established",
      "covers": [
        "ETC-011"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "An established communication session exists. The safe radio connection is lost.",
      "test_inputs": "Simulated loss of safe radio connection. Successful reconnection signal from radio system.",
      "assumptions": "The radio system allows a successful reconnection after the loss.",
      "steps": [
        {
          "no": 1,
          "action": "Simulate the loss of the safe radio connection.",
          "expected": "The OBU starts repeating attempts to set up a new safe radio connection."
        },
        {
          "no": 2,
          "action": "Simulate a successful establishment of the safe radio connection.",
