{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "AAL2 oturumunda inactivity timeout'unun tetiklenmesi",
      "covers": [
        "KDH-003"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "Kullanıcı AAL2 seviyesinde kimlik doğrulamasını tamamlamış ve aktif bir oturuma sahiptir. VBP SDD §14'te tanımlanan inactivity timeout değeri (örneğin 1 saat) bilinmektedir.",
      "test_inputs": "",
      "assumptions": "VBP SDD §14'te AAL2 için inactivity timeout'unun 1 saat olduğu varsayılmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Oturumda herhangi bir etkileşim yapılmadan inactivity timeout süresinin (1 saat) dolması beklenir.",
          "expected": "Sistem, oturumu sonlandırır ve kullanıcıyı yeniden kimlik doğrulaması yapmaya yönlendirir."
        },
        {
          "no": 2,
          "action": "Oturum sonlandıktan sonra kullanıcı, yalnızca parola veya biyometrik doğrulama ile (NIST SP 800-63B-4 §5.2'ye göre AAL2 için izin verilen yöntem) yeniden oturum açmayı dener.",
          "expected": "Sistem, genel timeout (overall timeout) henüz dolmadığı için bu basitleştirilmiş yeniden kimlik doğrulamasını kabul eder ve oturumu yeniden başlatır."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "AAL2 oturumunda overall timeout'unun tetiklenmesi",
      "covers": [
        "KDH-003"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "Kullanıcı AAL2 seviyesinde kimlik doğrulamasını tamamlamıştır. VBP SDD §14'te tanımlanan overall timeout değeri (örneğin 24 saat) bilinmektedir.",
      "test_inputs": "",
      "assumptions": "VBP SDD §14'te AAL2 için overall timeout'unun 24 saat olduğu varsayılmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Oturumda düzenli olarak etkileşim sağlanarak inactivity timeout'unun sıfırlanması sağlanır ve toplam oturum süresinin overall timeout değerine (24 saat) ulaşması beklenir.",
          "expected": "Sistem, inactivity timeout'unun sıfırlanmasına rağmen overall timeout'un dolmasıyla oturumu sonlandırır."
        },
        {
          "no": 2,
          "action": "Oturum sonlandıktan sonra kullanıcı, tam AAL2 kimlik doğrulaması (çok faktörlü veya iki ayrı faktör) ile yeniden oturum açmayı dener.",
          "expected": "Sistem, basitleştirilmiş yeniden kimlik doğrulamasına izin vermez ve tam AAL2 kimlik doğrulama sürecini zorunlu kılar."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Oturum aktivitesinin inactivity timeout'u sıfırlaması",
      "covers": [
        "KDH-003"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "Kullanıcı AAL2 seviyesinde aktif bir oturuma sahiptir.",
      "test_inputs": "",
      "assumptions": "VBP SDD §14'te AAL2 için inactivity timeout'unun 1 saat olduğu varsayılmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Oturum başlangıcından 30 dakika sonra kullanıcı, sistemde bir işlem gerçekleştirir (örneğin bir formu görüntüler).",
          "expected": "Sistem, inactivity timeout sayacını sıfırlar."
        },
        {
          "no": 2,
          "action": "İşlemden 30 dakika sonra (toplam 1 saat, ancak son aktiviteden 30 dakika) kullanıcı tekrar bir işlem gerçekleştirir.",
          "expected": "Oturum aktif kalır ve inactivity timeout sayacı tekrar sıfırlanır."
        },
        {
          "no": 3,
          "action": "Son aktiviteden 1 saat boyunca hiçbir işlem yapılmaz.",
          "expected": "Sistem, inactivity timeout'unun dolmasıyla oturumu sonlandırır."
        }
      ]
    },
    {
      "id": "TC-004",
      "title": "Başarılı yeniden kimlik doğrulamanın her iki timeout'u sıfırlaması",
      "covers": [
        "KDH-003"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "Kullanıcı AAL2 seviyesinde aktif bir oturuma sahiptir ve oturum süresi overall timeout'a yaklaşıyor olabilir.",
      "test_inputs": "",
      "assumptions": "VBP SDD §14'te AAL2 için overall timeout'unun 24 saat ve inactivity timeout'unun 1 saat olduğu varsayılmaktadır.",
      "steps": [
        {
          "no": 1,
          "action": "Oturum sırasında, inactivity timeout'unun dolmasına yakın bir zamanda (örneğin 59. dakikada) kullanıcı, sistem tarafından istenen yeniden kimlik doğrulamasını başarıyla tamamlar.",
          "expected": "Sistem, hem inactivity timeout'u hem de overall timeout'u sıfırlar."
        },
        {
          "no": 2,
          "action": "Yeniden kimlik doğrulamasından sonra 1 saat boyunca hiçbir işlem yapılmaz.",
          "expected": "Sistem, inactivity timeout'unun dolmasıyla oturumu sonlandırır (sıfırlanan sayaçtan itibaren)."
        }
      ]
    }
  ]
}

