{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Multiple authenticators disabled upon reaching failure threshold",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with both password and a second factor (e.g., OTP) enabled. The failure threshold is defined in VBP SDD §14 (assumed to be 5 for this test).",
      "test_inputs": "Valid username, incorrect password, incorrect second factor code.",
      "assumptions": "The threshold for consecutive failed attempts is 5. The system tracks failures per authenticator and per account.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the correct username, an incorrect password, and an incorrect second factor code.",
          "expected": "Authentication fails. The system records a failed attempt for both the password and the second factor authenticators."
        },
        {
          "no": 2,
          "action": "Repeat the login attempt with incorrect password and incorrect second factor code until the threshold (5th attempt) is reached.",
          "expected": "On the 5th failed attempt, the system disables both the password and the second factor authenticators for the account."
        },
        {
          "no": 3,
          "action": "Check the status of the account's authenticators in the system administration interface or via API.",
          "expected": "Both the password and the second factor authenticators are shown as disabled."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Single authenticator failure does not disable other authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account exists with both password and a second factor enabled. The failure threshold is 5.",
      "test_inputs": "Valid username, incorrect password, correct second factor code.",
      "assumptions": "The system only disables authenticators involved in the failed attempts. If the second factor is correct, it is not considered 'involved' in the failure in a way that triggers its own failure count, or the requirement implies that *both* must be involved in the consecutive failures to trigger the multi-authenticator disable rule. However, the requirement says 'If more than one authenticator is involved...'. If only password fails, only password is involved. Let's test that only the failing one is affected or that the multi-disable rule doesn't trigger incorrectly.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with the correct username, an incorrect password, and a correct second factor code.",
          "expected": "Authentication fails due to incorrect password. The system records a failed attempt for the password authenticator only."
        },
        {
          "no": 2,
          "action": "Repeat the login attempt with incorrect password and correct second factor code until the threshold (5th attempt) is reached.",
          "expected": "The password authenticator is disabled. The second factor authenticator remains enabled."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Verification of disabled authenticator status",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account has had both password and second factor disabled due to reaching the failure threshold.",
      "test_inputs": "Valid username, any password, any second factor code.",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Attempt to log in with the account using any password and any second factor code.",
          "expected": "The system rejects the login and indicates that the authenticators are disabled or the account is locked, preventing authentication."
        }
      ]
    }
  ]
}

